import React, { useState } from 'react';
import { signup, verifyOtp } from '../utils/api';

function SignupForm() {
  const [formData, setFormData] = useState({ email: '', password: '' });
  const [otp, setOtp] = useState('');
  const [step, setStep] = useState('signup'); // signup → verify → done
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSignupSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setMessage('');
    try {
      await signup(formData); // sends { email, password }
      setStep('verify'); // move to OTP verification step
      setMessage('OTP sent to your email. Please verify.');
    } catch (err) {
      setError(err.message || 'Signup failed');
    }
  };

  const handleOtpSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setMessage('');
    try {
      // ✅ Pass separate arguments instead of an object
      await verifyOtp(formData.email, otp);
      setMessage('Signup successful! Your email is verified.');
      setStep('done');
    } catch (err) {
      setError(err.message || 'Invalid OTP');
    }
  };

  return (
    <div>
      {step === 'signup' && (
        <form onSubmit={handleSignupSubmit}>
          <h2>Signup</h2>
          <input
            type="email"
            name="email"
            placeholder="Email"
            value={formData.email}
            onChange={handleChange}
            required
          />
          <input
            type="password"
            name="password"
            placeholder="Password"
            value={formData.password}
            onChange={handleChange}
            required
          />
          <button type="submit">Signup</button>
        </form>
      )}

      {step === 'verify' && (
        <form onSubmit={handleOtpSubmit}>
          <h2>Verify OTP</h2>
          <input
            type="text"
            placeholder="Enter OTP"
            value={otp}
            onChange={(e) => setOtp(e.target.value)}
            required
          />
          <button type="submit">Verify</button>
        </form>
      )}

      {message && <p style={{ color: 'green' }}>{message}</p>}
      {error && <p style={{ color: 'red' }}>{error}</p>}
    </div>
  );
}

export default SignupForm;
